<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f5f7fb">
  <title>CoopLending AI | Application Review</title><script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Noto+Sans+Devanagari:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>body{font-family:'DM Sans','Noto Sans Devanagari',sans-serif}.devanagari{font-family:'Noto Sans Devanagari',sans-serif}</style>
</head>
<body class="min-h-screen bg-slate-50 text-slate-900">
<header class="border-b border-slate-200 bg-white"><div class="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-4 lg:px-8">
  <div class="flex items-center gap-3"><div class="grid h-11 w-11 place-items-center rounded-xl bg-emerald-700 font-bold text-white">CL</div><div><h1 class="font-bold tracking-tight">CoopLending AI</h1><p class="text-xs text-slate-500">Maharashtra Cooperative Banking Extraction &amp; Audit</p></div></div>
  <div class="hidden items-center gap-2 rounded-full border border-emerald-100 bg-emerald-50 px-3 py-1.5 text-xs font-semibold text-emerald-800 sm:flex"><span class="h-2 w-2 rounded-full bg-emerald-500"></span> Secure review workspace</div>
</div></header>
<main class="mx-auto max-w-7xl px-5 py-8 lg:px-8 lg:py-10">
  <div class="mb-7"><p class="text-xs font-bold uppercase tracking-[.18em] text-emerald-700">Loan operations</p><h2 class="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">Application review desk</h2><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Extract borrower details from passbook or application OCR, then review the deterministic eligibility assessment and audit trail.</p></div>
  <div class="grid gap-6 lg:grid-cols-[.92fr_1.08fr]">
    <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6">
      <div class="mb-5 flex items-start justify-between"><div><h3 class="font-bold">Source document text</h3><p class="mt-1 text-sm text-slate-500">Paste OCR output in Marathi, English, or both.</p></div><span class="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-500">INPUT</span></div>
      <label for="rawText" class="mb-2 block text-xs font-semibold text-slate-600">OCR PASSBOOK / APPLICATION TEXT</label>
      <textarea id="rawText" rows="10" maxlength="20000" placeholder="उदा. राजारामबापू सह. बँक लि., खाते क्र: ९८४५०१२३८९..." class="devanagari w-full resize-y rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm leading-7 outline-none transition placeholder:text-slate-400 focus:border-emerald-600 focus:bg-white focus:ring-4 focus:ring-emerald-600/10"></textarea>
      <div class="mt-4 grid gap-3 sm:grid-cols-2"><button id="extractBtn" class="rounded-xl bg-emerald-700 px-4 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-emerald-800 disabled:cursor-wait disabled:opacity-60">Extract &amp; Score</button><button id="demoBtn" class="rounded-xl border border-amber-300 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-900 transition hover:bg-amber-100">⚡ Load Sample Marathi Passbook</button></div>
      <p class="mt-4 text-xs leading-5 text-slate-400">Submitted text is sent to the extraction worker and stored with the review record for audit.</p>
    </section>
    <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6" aria-live="polite">
      <div class="mb-5 flex items-start justify-between"><div><h3 class="font-bold">KYC extraction &amp; risk review</h3><p class="mt-1 text-sm text-slate-500">Structured borrower profile and scoring audit.</p></div><span class="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-500">RESULT</span></div>
      <div id="emptyState" class="grid min-h-[330px] place-items-center rounded-xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center"><div><div class="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-white text-xl shadow-sm">⌕</div><p class="mt-4 font-semibold text-slate-700">Ready for an application</p><p class="mt-1 max-w-xs text-sm leading-6 text-slate-500">Run an extraction to see borrower details, decision score, and risk flags.</p></div></div>
      <div id="result" class="hidden">
        <div id="decisionCard" class="mb-4 flex items-center justify-between rounded-xl border p-4"><div><p class="text-xs font-semibold uppercase tracking-wider opacity-70">Decision status</p><p id="status" class="mt-1 text-lg font-bold"></p></div><div class="text-right"><p class="text-xs font-semibold uppercase tracking-wider opacity-70">Eligibility score</p><p class="mt-1"><span id="score" class="text-3xl font-bold"></span><span class="text-sm font-semibold opacity-70"> / 100</span></p></div></div>
        <div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl border border-slate-100 p-4"><p class="text-xs font-semibold text-slate-400">APPLICANT · ENGLISH</p><p id="nameEn" class="mt-2 font-semibold"></p></div><div class="rounded-xl border border-slate-100 p-4"><p class="text-xs font-semibold text-slate-400">APPLICANT · MARATHI</p><p id="nameMr" class="devanagari mt-2 font-semibold"></p></div><div class="rounded-xl border border-slate-100 p-4"><p class="text-xs font-semibold text-slate-400">BANK / SOCIETY</p><p id="bank" class="mt-2 font-semibold"></p></div><div class="rounded-xl border border-slate-100 p-4"><p class="text-xs font-semibold text-slate-400">ACCOUNT NUMBER</p><p id="account" class="mt-2 font-semibold tabular-nums"></p></div><div class="rounded-xl border border-slate-100 p-4"><p class="text-xs font-semibold text-slate-400">MONTHLY INCOME</p><p id="income" class="mt-2 font-semibold"></p></div><div class="rounded-xl border border-emerald-100 bg-emerald-50/50 p-4"><p class="text-xs font-semibold text-emerald-700">MYSQL APPLICATION ID</p><p id="applicationId" class="mt-2 font-bold text-emerald-900"></p></div></div>
        <div class="mt-5"><p class="text-xs font-semibold uppercase tracking-wider text-slate-400">Risk flag audit</p><div id="flags" class="mt-2 flex flex-wrap gap-2"></div></div>
        <details class="mt-5 overflow-hidden rounded-xl border border-slate-200"><summary class="cursor-pointer bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-600">View raw JSON payload</summary><pre id="json" class="max-h-64 overflow-auto bg-slate-950 p-4 text-xs leading-5 text-emerald-200"></pre></details>
      </div><p id="error" class="mt-4 hidden rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800"></p>
    </section>
  </div>
  <footer class="mt-8 flex flex-col justify-between gap-2 border-t border-slate-200 pt-5 text-xs text-slate-400 sm:flex-row"><span>CoopLending AI · Review and audit</span><span>Decision support only · Final lending decisions remain with authorized staff</span></footer>
</main>
<script>
const rawText=document.getElementById('rawText'),extractBtn=document.getElementById('extractBtn'),demoBtn=document.getElementById('demoBtn');
const demo='राजारामबापू सह. बँक लि., खाते क्र: ९८४५०१२३८९, खातेदार: विठ्ठल सखाराम कदम, पॅन: ABCDE1234F, मासिक शिल्लक: रु. ३२,०००/-';
demoBtn.addEventListener('click',()=>{rawText.value=demo;run('demo')});extractBtn.addEventListener('click',()=>run('extract'));
async function run(action){document.getElementById('error').classList.add('hidden');if(action==='extract'&&!rawText.value.trim()){showError('Paste OCR text first, or use the sample passbook button.');return}const button=action==='demo'?demoBtn:extractBtn;button.disabled=true;button.textContent=action==='demo'?'Loading sample…':'Extracting and scoring…';try{const response=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action==='demo'?{action:'demo'}:{raw_text:rawText.value})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'The request failed.');render(payload)}catch(error){showError(error.message||'Could not complete extraction.')}finally{button.disabled=false;button.innerHTML=action==='demo'?'⚡ Load Sample Marathi Passbook':'Extract &amp; Score'}}
function showError(message){const node=document.getElementById('error');node.textContent=message;node.classList.remove('hidden')}
function render(data){document.getElementById('emptyState').classList.add('hidden');document.getElementById('result').classList.remove('hidden');const colors={AUTO_APPROVED:'border-emerald-200 bg-emerald-50 text-emerald-900',MANUAL_REVIEW:'border-amber-200 bg-amber-50 text-amber-900',REJECTED:'border-rose-200 bg-rose-50 text-rose-900'};document.getElementById('decisionCard').className='mb-4 flex items-center justify-between rounded-xl border p-4 '+(colors[data.status]||colors.MANUAL_REVIEW);document.getElementById('status').textContent=data.status.replaceAll('_',' ');document.getElementById('score').textContent=data.eligibility_score;document.getElementById('nameEn').textContent=data.applicant_name_english;document.getElementById('nameMr').textContent=data.applicant_name_marathi;document.getElementById('bank').textContent=data.bank_or_society_name;document.getElementById('account').textContent=data.account_number;document.getElementById('income').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(data.monthly_income);document.getElementById('applicationId').textContent='#'+data.application_id;const flags=document.getElementById('flags');flags.replaceChildren();const items=data.risk_flags?.length?data.risk_flags:['No risk flags'];items.forEach(flag=>{const tag=document.createElement('span');tag.className=data.risk_flags?.length?'rounded-full border border-amber-200 bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-800':'rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-800';tag.textContent=flag;flags.append(tag)});document.getElementById('json').textContent=JSON.stringify(data,null,2)}
</script>
</body></html>
